// Nodo de parseo GVM/GMP — VERSIÓN DE PREPARACIÓN CON DATOS SIMULADOS.
//
// Contexto: GVM todavía no está instalado (Fase 2d, bloqueada por RAM insuficiente
// en la notebook de desarrollo). Este nodo se construyó y probó contra
// gvm-integration/mock-get-reports-response.xml, un XML simulado pero basado en
// CVEs reales aplicables a las versiones detectadas en target1 (ver ese archivo
// para el detalle y las fuentes consultadas).
//
// Cuando GVM esté disponible: el nodo "Execute Command" anterior a este va a
// invocar `gvm-cli` de verdad en vez de `cat gvm-integration/mock-...xml`, y este
// código de parseo NO debería necesitar cambios (mismo formato de entrada
// esperado). Verificar igual contra la respuesta real la primera vez.
//
// Decisión de diseño: los hallazgos de GVM NO se insertan como filas nuevas.
// Se usan para ACTUALIZAR (UPDATE) las filas que el pipeline de Nmap ya insertó
// en vulnerability_scans (cruzando por host_ip + port), completando cve_id,
// severity_score, severity_label, description y solution. Resultado: una sola
// fila por hallazgo real, enriquecida en dos pasadas (reconocimiento -> CVE),
// no filas duplicadas. Este nodo prepara esos datos; el UPDATE en sí lo hace el
// nodo Postgres siguiente (fuera del alcance de esta preparación).

const { parseStringPromise } = require('xml2js');

// Traducción de los niveles de threat de GMP a las etiquetas en español que
// usa nuestro esquema (columna severity_label: Crítica | Alta | Media | Baja | Ninguna).
const THREAT_TO_LABEL = {
  Critical: 'Crítica',
  High: 'Alta',
  Medium: 'Media',
  Low: 'Baja',
  Log: 'Ninguna',
  Debug: 'Ninguna',
};

function extraerTag(tagsString, clave) {
  // El campo "tags" de un NVT viene como pares clave=valor separados por "|",
  // ej: "summary=...|insight=...|solution=...". Convención documentada por
  // Greenbone; no hay subelementos separados para cada una en get_reports.
  if (!tagsString) return null;
  const partes = tagsString.split('|');
  for (const parte of partes) {
    const idx = parte.indexOf('=');
    if (idx === -1) continue;
    const k = parte.slice(0, idx).trim();
    const v = parte.slice(idx + 1).trim();
    if (k === clave) return v || null;
  }
  return null;
}

const results = [];

for (const item of $input.all()) {
  const rawXml = item.json.stdout;

  if (!rawXml) {
    throw new Error('El item no contiene stdout con el XML de get_reports. Verificar el nodo Execute Command anterior.');
  }

  let parsed;
  try {
    parsed = await parseStringPromise(rawXml, { explicitArray: true });
  } catch (err) {
    results.push({
      json: {
        parseError: true,
        errorMessage: err.message,
        rawXmlSnippet: rawXml.slice(0, 200),
      },
    });
    continue;
  }

  const reportResults =
    parsed?.get_reports_response?.report?.[0]?.report?.[0]?.results?.[0]?.result ?? [];

  if (reportResults.length === 0) {
    results.push({
      json: {
        parseError: false,
        noFindings: true,
        message: 'get_reports no devolvió resultados (0 hallazgos).',
      },
    });
    continue;
  }

  for (const r of reportResults) {
    const hostIp = r?.host?.[0] ?? null;
    const portRaw = r?.port?.[0] ?? null; // formato "80/tcp"
    const [portNum, protocol] = portRaw ? portRaw.split('/') : [null, null];

    const nvt = r?.nvt?.[0] ?? {};
    const cve = nvt?.cve?.[0] ?? null;
    const tags = nvt?.tags?.[0] ?? null;

    const threat = r?.threat?.[0] ?? 'Log';
    const severityScore = Number(r?.severity?.[0] ?? 0);

    results.push({
      json: {
        parseError: false,
        hostIp,
        port: portNum ? Number(portNum) : null,
        protocol: protocol ?? null,
        cveId: cve && cve !== 'NOCVE' ? cve : null,
        severityScore,
        severityLabel: THREAT_TO_LABEL[threat] ?? 'Ninguna',
        description: extraerTag(tags, 'summary') ?? r?.description?.[0] ?? null,
        solution: extraerTag(tags, 'solution') ?? null,
      },
    });
  }
}

return results;

// Nodo "Adaptar Mock + Resumen" — SOLO para el workflow de preview
// "MOCK - GVM Preview". NO se usa en el workflow real ni toca PostgreSQL.
//
// Hace dos cosas en un solo paso, para simplificar el workflow de preview:
// 1. Convierte los campos camelCase que produce nodo-gvm-parseo-mock.js
//    (hostIp, cveId, severityScore...) al snake_case que espera
//    nodo8-generar-informe.js (host_ip, cve_id...), porque ese nodo fue
//    diseñado para leer filas tal cual las devuelve una consulta SQL.
// 2. Arma el objeto "summary" (scanUuid, targetRange, etc.) en memoria,
//    sin ningún INSERT real.
//
// La tabla PORT_A_SERVICIO es una comodidad SOLO para este preview: en el
// pipeline real, service_name/service_version ya vienen guardados en
// vulnerability_scans desde el paso de Nmap (no hace falta inventarlos).

const crypto = require('crypto');

const PORT_A_SERVICIO = {
  21: { service_name: 'ftp', service_version: 'vsftpd 3.0.3' },
  22: { service_name: 'ssh', service_version: 'OpenSSH 7.6p1 Ubuntu 4ubuntu0.7' },
  80: { service_name: 'http', service_version: 'Apache httpd 2.4.29 ((Ubuntu))' },
};

const itemsGvm = $input.all();

if (itemsGvm.length === 0) {
  throw new Error('No hay items de entrada: el mock de GVM no produjo ningún resultado.');
}

const findingsAdaptados = itemsGvm.map((item) => {
  const j = item.json;
  const servicio = PORT_A_SERVICIO[j.port] ?? { service_name: null, service_version: null };
  return {
    scan_id: 'MOCK-PREVIEW',
    host_ip: j.hostIp,
    hostname: 'target1',
    port: j.port,
    protocol: j.protocol,
    service_name: servicio.service_name,
    service_version: servicio.service_version,
    cve_id: j.cveId,
    severity_score: j.severityScore,
    severity_label: j.severityLabel,
    description: j.description,
    solution: j.solution,
  };
});

const uniqueHosts = new Set(findingsAdaptados.map((f) => f.host_ip).filter(Boolean));

// Guardamos el resumen y los hallazgos en el mismo item (índice 0) para que
// el siguiente nodo (una copia de nodo8-generar-informe.js) pueda leer todo
// sin depender de $('Resumen Scan History'), que no existe en este preview.
return [
  {
    json: {
      summary: {
        scanUuid: 'MOCK-PREVIEW-' + crypto.randomUUID(),
        targetRange: Array.from(uniqueHosts).join(', '),
        startedAt: new Date().toISOString(),
        finishedAt: new Date().toISOString(),
        hostCount: uniqueHosts.size,
        findingCount: findingsAdaptados.length,
      },
      findings: findingsAdaptados,
    },
  },
];

// Nodo 8 — Generador del informe Markdown — VERSIÓN PREVIEW.
//
// Copia funcionalmente idéntica a nodo8-generar-informe.js. La ÚNICA
// diferencia son las dos primeras líneas: en el pipeline real, findings y
// summary vienen de PostgreSQL (vía $input y $('Resumen Scan History'));
// acá vienen del nodo "Adaptar Mock + Resumen" anterior, todo en memoria.
// Si el pipeline real cambia esta lógica de armado del informe, hay que
// replicar el cambio acá también (o, mejor, borrar este preview cuando ya
// no haga falta).

const entrada = $input.first().json;
const findings = entrada.findings;
const summary = entrada.summary;

if (findings.length === 0) {
  throw new Error('No se recibieron hallazgos del nodo "Adaptar Mock + Resumen".');
}

// --- Inventario de hosts ---
const hostMap = new Map();
for (const f of findings) {
  if (!hostMap.has(f.host_ip)) {
    hostMap.set(f.host_ip, { hostname: f.hostname, count: 0, ports: [] });
  }
  const entry = hostMap.get(f.host_ip);
  entry.count += 1;
  entry.ports.push(f.port);
}

let hostInventory = '| Host (IP) | Hostname | Puertos detectados | Cant. hallazgos |\n';
hostInventory += '|---|---|---|---|\n';
for (const [ip, data] of hostMap.entries()) {
  hostInventory += `| ${ip} | ${data.hostname ?? 'N/D'} | ${data.ports.join(', ')} | ${data.count} |\n`;
}

// --- Agrupación por severidad ---
const hasSeverityData = findings.some((f) => f.severity_label);

let detailSection = '';
if (hasSeverityData) {
  const bySeverity = { Crítica: [], Alta: [], Media: [], Baja: [], Ninguna: [] };
  for (const f of findings) {
    const label = f.severity_label ?? 'Ninguna';
    (bySeverity[label] ?? bySeverity.Ninguna).push(f);
  }
  for (const [label, items] of Object.entries(bySeverity)) {
    if (items.length === 0) continue;
    detailSection += `\n### ${label} (${items.length})\n\n`;
    for (const f of items) {
      detailSection += `- **${f.host_ip}:${f.port}/${f.protocol}** — ${f.service_name} (${f.service_version})\n`;
      if (f.cve_id) detailSection += `  - CVE: ${f.cve_id}\n`;
      if (f.description) detailSection += `  - Descripción: ${f.description}\n`;
      if (f.solution) detailSection += `  - Solución recomendada: ${f.solution}\n`;
    }
  }
} else {
  detailSection += `\n### Hallazgos de reconocimiento (Nmap) — pendientes de correlación con GVM\n\n`;
  detailSection += `> Estos ${findings.length} hallazgos provienen de la detección de servicios y versiones de Nmap. `;
  detailSection += `Todavía no fueron correlacionados contra una base de datos de CVE (GVM/Greenbone, Fase 2d del proyecto). `;
  detailSection += `No deben interpretarse como vulnerabilidades confirmadas.\n\n`;
  for (const f of findings) {
    detailSection += `- **${f.host_ip}:${f.port}/${f.protocol}** — ${f.service_name}: ${f.service_version}\n`;
  }
}

// --- Recomendaciones generales ---
const recommendations = [
  'Correlacionar estos hallazgos con una base de datos de CVE (GVM/Greenbone) antes de tomar acciones de remediación.',
  'Mantener actualizado el software de cada servicio detectado a su versión estable más reciente.',
  'Restringir el acceso de red a los puertos detectados únicamente a los hosts que efectivamente lo necesiten.',
  'Repetir este escaneo de forma periódica para detectar desviaciones respecto de esta línea base.',
];

const report = `# [PREVIEW - DATOS SIMULADOS, NO REALES] Informe de Escaneo de Red

> ⚠️ Este informe se generó con datos de GVM SIMULADOS (ver gvm-integration/README.md).
> No representa un escaneo real. Sirve para validar que el pipeline completo
> (parseo -> agrupación por severidad -> informe) funciona antes de tener GVM instalado.

**ID de escaneo:** ${summary.scanUuid}
**Rango/objetivo:** ${summary.targetRange}
**Inicio:** ${summary.startedAt}
**Fin:** ${summary.finishedAt}
**Hosts analizados:** ${summary.hostCount}
**Hallazgos totales:** ${findings.length} de ${findings.length} recuperados (correspondencia 1:1 verificada)

## Inventario de hosts

${hostInventory}

## Detalle de hallazgos
${detailSection}

## Recomendaciones generales

${recommendations.map((r) => `- ${r}`).join('\n')}

---
*Informe generado automáticamente. PREVIEW con datos simulados, scan_id = ${summary.scanUuid}.*
`;

return [{ json: { reportMarkdown: report, findingCount: findings.length } }];
